from lib import *
S = SS('x27')
steps = [
    step("Spring Framework 7 内置了重试(org.springframework.resilience.annotation.Retryable,要加 @EnableResilientMethods),不再依赖独立项目 spring-retry。默认值 maxRetries = 3、delay = 1000 ms:前 2 次失败的方法,执行时刻是 5、1014、2019 ms,第 3 次成功返回 ok@3,每次间隔约 1 秒。改成 maxRetries = 4、delay = 100:执行时刻是 0、104、206 ms,间隔约 100 ms。maxRetries 是重试次数,总共执行 1 加 maxRetries 次。", t=tl(S(1)), mark=lidx(S(1), '1014 ms  defaults 第 2 次执行', '104 ms  fast 第 2 次执行'), done=lidx(S(1), 'defaults 第 1 次执行', '2019 ms  defaults 第 3 次执行', 'ok@3'), b=bars([['默认 delay ms', 1000, '1000'], ['第 2 次执行的时刻 ms(默认)', 1014, '1014'], ['第 2 次执行的时刻 ms(delay=100)', 104, '104']], 1014, done=[0], cur=[1], mark=[2]), kv=KV([['默认 maxRetries', '3(共最多 4 次执行)'], ['默认 delay', '1000 ms'], ['第 2、3 次执行', '约 1014、2019 ms'], ['delay = 100', '约 104、206 ms']], ['默认 delay'])),
    step("指数退避。maxRetries = 5、delay = 100、multiplier = 2、maxDelay = 500,方法总是失败:6 次执行的时刻是 5、113、317、721、1226、1731 ms,间隔约 108、204、404、505、505 ms——100、200、400、然后被 maxDelay 限制在 500。最后抛出的是最后一次的原始异常(IllegalStateException:失败 6)。", t=tl(S(2)), mark=lidx(S(2), '1731 ms  backoff 第 6 次执行', '→ 抛 IllegalStateException: 失败 6'), done=lidx(S(2), '113 ms  backoff', '317 ms  backoff', '721 ms  backoff', '1226 ms  backoff'), b=bars([['第 1 到 2 次的间隔 ms', 108, '108'], ['第 2 到 3 次的间隔 ms', 204, '204'], ['第 3 到 4 次的间隔 ms', 404, '404'], ['第 4 到 5 次的间隔 ms', 505, '505(被 maxDelay 限制)'], ['第 5 到 6 次的间隔 ms', 505, '505']], 505, done=[0, 1, 2], mark=[3, 4]), kv=KV([['delay / multiplier', '100 乘 2 逐次翻倍'], ['maxDelay = 500', '间隔上限'], ['6 次执行', '1 加 5 次重试'], ['最终异常', '最后一次的原始异常']], ['maxDelay = 500'])),
    step("哪些异常会被重试。includes = IOException:抛 IOException 被重试,共执行 4 次(默认 maxRetries = 3);抛 IllegalStateException 不重试,只执行 1 次。excludes = IllegalArgumentException:IllegalArgumentException 不重试(1 次),IllegalStateException 重试(4 次)。嵌套的原因也参与匹配:抛 RuntimeException、cause 是 IOException,includes = IOException、maxRetries = 2 时执行了 3 次。predicate:消息以“可重试”开头的重试(4 次),别的不重试(1 次)。重试用完之后抛出的就是原始异常,没有被包装。", t=tl(S(3)), mark=lidx(S(3), '抛 IllegalStateException: ise', '抛 IllegalArgumentException: iae', '别重试'), done=lidx(S(3), '173 ms  onlyIo', '340 ms  excl', '446 ms  nested', '612 ms  pred'), b=bars([['includes IOException,抛 IOException:执行次数', 4, '4'], ['includes IOException,抛 ISE:执行次数', 1, '1'], ['excludes IAE,抛 IAE:执行次数', 1, '1'], ['excludes IAE,抛 ISE:执行次数', 4, '4'], ['cause 是 IOException(maxRetries=2):执行次数', 3, '3']], 4, done=[0, 3, 4], mark=[1, 2]), kv=KV([['includes', '只重试这些(包括嵌套的 cause)'], ['excludes', '这些不重试'], ['predicate', '自定义判断,可以注入依赖'], ['用完后', '抛原始异常']], ['includes'])),
    step("次数用完与超时。maxRetries = 2、总是失败:执行了 3 次(4、62、118 ms),调用者收到的是 IllegalStateException:总是失败,原始异常没有被包装。timeout = 500 ms、delay = 200 ms、maxRetries = 10、总是失败:执行了 3 次(0、204、408 ms),第 4 次本来在 612 ms,已经超过 500 ms 的总时限,所以不再重试,调用者收到最后那次的 IllegalStateException。timeout 限制的是包括等待在内的总时间。", t=tl(S(4)), mark=lidx(S(4), '408 ms  withTimeout'), done=lidx(S(4), '118 ms  exhaust', '119 ms  → 抛 IllegalStateException: 总是失败'), b=bars([['maxRetries = 2:执行次数', 3, '3'], ['timeout = 500 ms(maxRetries = 10):执行次数', 3, '3'], ['timeout ms', 500, '500'], ['最后一次执行的时刻 ms', 408, '408']], 500, done=[0], cur=[1], mark=[2, 3]), kv=KV([['次数用完', '抛最后的原始异常'], ['timeout', '限制包括等待的总时间'], ['maxRetries = 10 却只执行 3 次', '被 timeout 截断'], ['下一次本来在', '约 612 ms,超过 500 ms']], ['timeout'])),
    step("编程式的 RetryTemplate 与 RetryListener(org.springframework.core.retry)。maxRetries = 2、delay = 50 ms、前 2 次失败:第 1 次执行在 0 ms,第 2 次执行(58 ms 左右)前触发 beforeRetry,第 2 次失败触发 onRetryFailure,第 3 次在 113 ms 左右执行并在 114 ms 触发 onRetrySuccess,返回 ok。注意第 1 次执行失败没有触发 onRetryFailure,监听器只管“重试”。总是失败时:两次重试的 beforeRetry 与 onRetryFailure 之后触发 onRetryPolicyExhaustion,抛 RetryException:Retry policy for operation ... exhausted,最后的原因是 IllegalStateException,suppressed 有 2 个。RetryTemplate 次数用完抛 RetryException,而 @Retryable 抛原始异常。", t=tl(S(5)), mark=lidx(S(5), 'RetryListener.onRetryPolicyExhaustion', '→ 次数用完'), done=lidx(S(5), 'RetryListener.beforeRetry', 'RetryListener.onRetryFailure(编程式失败 2)', 'RetryListener.onRetrySuccess', '→ 返回 ok'), b=bars([['RetryTemplate 失败后重试的次数', 2, '2'], ['第 1 次执行触发 onRetryFailure', 0, '否'], ['次数用完时的 suppressed 异常个数', 2, '2']], 2, done=[0], mark=[1], cur=[2]), kv=KV([['RetryTemplate.execute', '次数用完抛 RetryException'], ['@Retryable', '次数用完抛原始异常'], ['RetryListener', 'beforeRetry、onRetryFailure、onRetrySuccess、onRetryPolicyExhaustion'], ['第 1 次执行失败', '不算重试,不触发 onRetryFailure']], ['RetryTemplate.execute'])),
    step("同一个包里的 @ConcurrencyLimit。8 个线程同时调用一个耗时 300 ms 的方法。@ConcurrencyLimit(2):8 个全部成功,总共花 1219 ms(8 个除以 2 个一批,共 4 批,每批 300 ms),方法内观察到的最大并发是 2。policy = REJECT:成功 2 个,被拒绝 6 个(InvocationRejectedException),全部结束花了 305 ms。默认的 BLOCK 策略让多余的调用排队等待,REJECT 让它们直接失败。", t=tl(S(6)), mark=lidx(S(6), 'policy = REJECT'), done=lidx(S(6), '@ConcurrencyLimit(2),8 个线程'), b=bars([['BLOCK:成功', 8, '8'], ['BLOCK:总耗时 ms', 1219, '1219'], ['REJECT:成功', 2, '2'], ['REJECT:被拒绝', 6, '6'], ['REJECT:总耗时 ms', 305, '305']], 1219, done=[0, 2], cur=[1, 4], mark=[3]), kv=KV([['BLOCK(默认)', '超出限制的排队,最大并发 2'], ['REJECT', '超出限制的立刻抛 InvocationRejectedException'], ['耗时', '1219 对 305 ms'], ['用途', '保护下游,限制并发']], ['REJECT'])),
]
A = mkartx('x27', 27, 'Spring,Retryable,重试,退避,ConcurrencyLimit,真实验证,动画演示',
    '实测 Spring Framework 7 内置的 @Retryable:默认 maxRetries = 3、delay = 1000 ms(执行时刻 5、1014、2019 ms);multiplier = 2、maxDelay = 500 时间隔 100、200、400、500、500;includes / excludes / predicate 筛选异常(嵌套的 cause 也参与匹配);次数用完抛原始异常,timeout 把 maxRetries = 10 截断成 3 次;RetryTemplate 次数用完抛 RetryException;@ConcurrencyLimit(2) 把最大并发限制成 2。',
    'Spring 7 把重试做进了框架本身:@Retryable 默认怎么重试?退避怎么算?哪些异常会被重试?用完次数之后调用者看到什么?RetryTemplate 又是什么样?这篇在 Spring Framework 7.0.9 上用带时间戳的时间线逐项验证,也顺带验证了同包的 @ConcurrencyLimit。',
    [('1 加 3 次', '默认 maxRetries = 3 时一个总是失败的方法最多执行的次数(delay 默认 1000 ms)'), ('100、200、400、500、500', 'delay = 100、multiplier = 2、maxDelay = 500 时各次重试之间的等待(ms,实测约 108、204、404、505、505)'), ('1219 对 305 ms', '8 个线程调用耗时 300 ms 的方法,@ConcurrencyLimit(2) 的 BLOCK 与 REJECT 策略的总耗时')],
    [('默认与基本用法', '<p>@EnableResilientMethods 加 @Retryable,默认最多重试 3 次、间隔 1 秒。</p>'),
     ('退避', '<p>delay、multiplier、maxDelay 控制间隔,maxDelay 封顶。</p>'),
     ('异常筛选', '<p>includes、excludes、predicate 决定哪些异常重试,嵌套的 cause 也参与匹配。</p>'),
     ('用完与超时', '<p>次数用完抛原始异常,timeout 限制包括等待在内的总时间。</p>'),
     ('RetryTemplate', '<p>编程式重试,监听器只管“重试”,次数用完抛 RetryException。</p>'),
     ('@ConcurrencyLimit', '<p>限制同一个方法的并发数,多余的排队或拒绝。</p>')],
    steps,
    [ENV_X + '。用不带 Boot 的 Spring Framework 7.0.9 的 @EnableResilientMethods 与 spring-core 里的 org.springframework.core.retry(查了 7.0.9 的源码确认属性名和默认值);时间戳每次运行有几 ms 的抖动,间隔写的是实测值',
     '没有验证:独立项目 spring-retry 的 @Retryable / @Recover(Spring 7 内置的这一套没有 @Recover);jitter 抖动的效果;响应式返回类型(Mono、Flux)与 CompletableFuture 的重试;@Retryable 与 @Transactional 的组合顺序;maxRetriesString 等配置占位符;重试时的线程阻塞(重试期间是在调用线程里 sleep)'],
    '@Retryable 与 @ConcurrencyLimit')
